SELECT ?zone ?zname ?tpoint ?cp WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?zname .
  ?zone brick:hasPoint ?tpoint .
  ?tpoint a brick:ZoneTemperatureSensor .
} LIMIT 20

SELECT DISTINCT ?type WHERE {
  ?p a ?type .
  FILTER (regex(str(?type), "Setpoint|setpoint", "i"))
} LIMIT 40

SELECT ?zone ?zname WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?zname .
} LIMIT 40

SELECT DISTINCT ?type WHERE {
  ?p a ?type .
  FILTER (regex(str(?type), "Temperature", "i"))
} LIMIT 40

SELECT ?type (COUNT(?s) AS ?n) WHERE {
  ?s a ?type .
} GROUP BY ?type ORDER BY DESC(?n) LIMIT 60

SELECT ?room ?rname ?tpoint ?ttype ?tsid WHERE {
  ?room a brick:Room .
  ?room rdfs:label ?rname .
  ?room brick:hasPoint ?tpoint .
  ?tpoint a ?ttype .
  FILTER (regex(str(?ttype), "Temperature_Sensor", "i"))
  OPTIONAL { ?tpoint ref:hasTimeseriesId ?tsid }
} LIMIT 40

SELECT ?room ?rname ?cpoint ?ctype ?cid WHERE {
  ?room a brick:Room .
  ?room rdfs:label ?rname .
  ?room brick:hasPoint ?cpoint .
  ?cpoint a ?ctype .
  FILTER (regex(str(?ctype), "Cooling_Temperature_Setpoint", "i"))
  OPTIONAL { ?cpoint ref:hasTimeseriesId ?cid }
} LIMIT 40

SELECT ?room ?rname ?tpoint ?tsid WHERE {
  ?room a brick:Room .
  ?room rdfs:label ?rname .
  ?room brick:hasPoint ?tpoint .
  ?tpoint a brick:Zone_Air_Temperature_Sensor .
  OPTIONAL { ?tpoint ref:hasTimeseriesId ?tsid }
} ORDER BY ?rname

SELECT ?holder ?hname ?cpoint ?cid WHERE {
  ?cpoint a brick:Zone_Air_Cooling_Temperature_Setpoint .
  OPTIONAL { ?holder brick:hasPoint ?cpoint . ?holder rdfs:label ?hname }
  OPTIONAL { ?cpoint ref:hasTimeseriesId ?cid }
} ORDER BY ?hname

SELECT ?zone ?zname ?point ?ptype ?tsid WHERE {
  ?zone a brick:Room .
  ?zone rdfs:label ?zname .
} LIMIT 5

SELECT ?point ?ptype ?tsid WHERE {
  ?point a ?ptype .
  FILTER (regex(str(?ptype), "Zone_Air_(Cooling|Temperature)_", "i"))
  ?point ref:hasTimeseriesId ?tsid
} ORDER BY ?point

